<?php
declare(strict_types=1);require_once dirname(__DIR__).'/bootstrap.php';require_method('POST');$u=current_user();require_csrf();$id=string_value(input(),'id',36);authorize_campaign($id);$pdo=db();$pdo->beginTransaction();try{$s=$pdo->prepare("SELECT id FROM campaigns WHERE tenant_id=? AND public_id=? AND status IN ('DRAFT','QUEUED','RUNNING','PAUSED') FOR UPDATE");$s->execute([$u['tenant_id'],$id]);$cid=$s->fetchColumn();if(!$cid)throw new ApiError(409,'This campaign cannot be cancelled.');$pdo->prepare("UPDATE campaign_recipients SET status='CANCELLED' WHERE tenant_id=? AND campaign_id=? AND status IN ('PENDING','RETRY')")->execute([$u['tenant_id'],$cid]);$pdo->prepare("UPDATE campaigns SET status='CANCELLED',pending_count=0,completed_at=UTC_TIMESTAMP() WHERE tenant_id=? AND id=?")->execute([$u['tenant_id'],$cid]);$pdo->prepare('DELETE FROM lead_campaign_claims WHERE tenant_id=? AND campaign_id=?')->execute([$u['tenant_id'],$cid]);$pdo->commit();}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();throw $e;}audit('campaign.cancelled','campaign',$id);respond(['status'=>'CANCELLED']);
